CREATE SCHEMA ada_history;
CREATE TABLE ada_history.meta(marker text PRIMARY KEY,scope text NOT NULL CHECK(scope='COPY ONLY'));
CREATE TABLE ada_history.customers(source_id text NOT NULL,ada_code varchar(20) NOT NULL,name text,phone text,email text,branch_code text,active text,source_payload jsonb NOT NULL,payload_hash char(64) NOT NULL,source_snapshot uuid NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(source_id,ada_code),CHECK(source_payload->>'FTCstCode'=ada_code));
CREATE INDEX history_customer_phone ON ada_history.customers(phone);
CREATE TABLE ada_history.receipts(source_id text NOT NULL,receipt_key char(64) NOT NULL,branch_code text NOT NULL,pos_code text NOT NULL,doc_no text NOT NULL,doc_type text NOT NULL CHECK(doc_type IN('1','9')),customer_code varchar(20) NOT NULL CHECK(customer_code NOT IN('','0')),sale_date date,sale_time time without time zone,raw_sale_date text,grand_total numeric,total_before_discount numeric,paid_status text,doc_status text,refund_status text,original_doc_no text,source_payload jsonb NOT NULL,payload_hash char(64) NOT NULL,source_snapshot uuid NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(source_id,receipt_key),UNIQUE(source_id,branch_code,pos_code,doc_type,doc_no),UNIQUE(source_id,doc_no));
CREATE INDEX history_receipt_customer ON ada_history.receipts(source_id,customer_code,sale_date DESC,sale_time DESC);
CREATE TABLE ada_history.lines(source_id text NOT NULL,line_key char(64) NOT NULL,receipt_key char(64) NOT NULL,seq bigint NOT NULL,sku text,product_name text,barcode text,unit_code text,unit_name text,quantity numeric,quantity_base numeric,unit_price numeric,line_total numeric,item_status text,refund_status text,source_payload jsonb NOT NULL,payload_hash char(64) NOT NULL,source_snapshot uuid NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(source_id,line_key),UNIQUE(source_id,receipt_key,seq),FOREIGN KEY(source_id,receipt_key) REFERENCES ada_history.receipts(source_id,receipt_key));
CREATE TABLE ada_history.member_links(member_id uuid NOT NULL,source_id text NOT NULL,ada_code varchar(20) NOT NULL,approval_reference text NOT NULL,PRIMARY KEY(source_id,ada_code),FOREIGN KEY(source_id,ada_code) REFERENCES ada_history.customers(source_id,ada_code));
CREATE TABLE ada_history.checkpoints(snapshot_id uuid NOT NULL,kind text NOT NULL,last_key char(64) NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(snapshot_id,kind));
CREATE TABLE ada_history.change_journal(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,entity text NOT NULL,source_key text NOT NULL,old_hash char(64) NOT NULL,new_hash char(64) NOT NULL,changed_at timestamptz NOT NULL DEFAULT now());
CREATE VIEW ada_history.purchase_history AS SELECT r.*,c.name customer_name FROM ada_history.receipts r JOIN ada_history.customers c ON c.source_id=r.source_id AND c.ada_code=r.customer_code;
CREATE VIEW ada_history.member_purchase_history AS SELECT l.member_id,r.* FROM ada_history.purchase_history r JOIN ada_history.member_links l ON l.source_id=r.source_id AND l.ada_code=r.customer_code;
